const defaultState = {
  settings:structuredClone(DEFAULT_SETTINGS), products:structuredClone(DEFAULT_PRODUCTS), cart:[], wishlist:[],
  profile:{name:'',email:'',phone:'',address:'',city:'',state:'',pincode:'',landmark:''}, orders:[], searches:{}, reviews:[]
};

function mergeDeep(base, incoming){
  if(Array.isArray(base)) return Array.isArray(incoming) ? incoming : structuredClone(base);
  if(base && typeof base==='object'){
    const out={...base};
    for(const [k,v] of Object.entries(incoming||{})) out[k]=mergeDeep(base[k],v);
    return out;
  }
  return incoming===undefined?base:incoming;
}
function loadState(){try{return mergeDeep(defaultState,JSON.parse(localStorage.getItem(KEY)||'null')||{})}catch{return structuredClone(defaultState)}}
let state=loadState();
let activeOfferTimer=null;

function normalizeProduct(p){
  p.sizes=Object.assign({S:false,M:false,L:false,XL:false,XXL:false},p.sizes||{});
  const raw=Array.isArray(p.colors)?p.colors:[];
  p.colors=raw.map(c=>typeof c==='string'?{name:c,hex:COLOR_LIBRARY[c]||'#9aa0a8',enabled:true}:Object.assign({name:'Custom',hex:'#999999',enabled:true},c));
  if(!p.colors.length)p.colors=[{name:'Black',hex:'#111214',enabled:true}];
  p.images=Array.isArray(p.images)&&p.images.length?p.images:[IMG.hero];
  p.features=Array.isArray(p.features)?p.features:[];
  return p;
}
state.products=state.products.map(normalizeProduct);
state.settings=mergeDeep(DEFAULT_SETTINGS,state.settings||{});
state.settings.payments=Object.assign({},DEFAULT_SETTINGS.payments,state.settings.payments||{});
state.settings.cashfree=Object.assign({},DEFAULT_SETTINGS.cashfree,state.settings.cashfree||{});
state.settings.offer=Object.assign({},DEFAULT_SETTINGS.offer,state.settings.offer||{});
state.settings.theme=Object.assign({},DEFAULT_SETTINGS.theme,state.settings.theme||{});
state.orders=(state.orders||[]).map(ensureOrderTracking);
save();

function save(){localStorage.setItem(KEY,JSON.stringify(state))}
function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function money(n){return `${state.settings.currency||'₹'}${Number(n||0).toLocaleString('en-IN')}`}
function toast(msg){const el=document.getElementById('toast');if(!el)return;el.textContent=msg;el.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>el.classList.remove('show'),2500)}
function product(id){return state.products.find(p=>p.id===id)}
function totalItems(){return state.cart.reduce((a,x)=>a+Number(x.qty||0),0)}
function cartSubtotal(){return state.cart.reduce((a,x)=>a+(product(x.id)?.price||0)*Number(x.qty||0),0)}
function shipping(){return Number(state.settings.shipping||0)}
function cartTotal(discount=0){return Math.max(0,cartSubtotal()+shipping()-discount)}
function profileReadyForCheckout(){const p=state.profile;return Boolean(String(p.name||'').trim()&&String(p.phone||'').trim()&&String(p.address||'').trim()&&String(p.city||'').trim()&&/^\d{6}$/.test(String(p.pincode||'')))}
function ensureOrderTracking(o){
  o=o||{};o.status=o.status||'Placed';o.createdAt=o.createdAt||new Date().toISOString();
  o.expectedDeliveryDate=o.expectedDeliveryDate||addDaysISO(o.createdAt,5);o.deliveryWindow=o.deliveryWindow||'10 AM – 9 PM';
  o.trackingNumber=o.trackingNumber||'';o.courier=o.courier||'';o.customerNote=o.customerNote||'';o.lastUpdatedAt=o.lastUpdatedAt||o.createdAt;
  o.timeline=Array.isArray(o.timeline)?o.timeline:[];if(!o.timeline.some(x=>x.status==='Placed'))o.timeline.unshift({status:'Placed',at:o.createdAt,note:'Order received'});
  o.paymentStatus=o.paymentStatus||'pending';o.advancePaid=Number(o.advancePaid||0);o.remainingDue=Number(o.remainingDue??Math.max(0,Number(o.total||0)-o.advancePaid));
  return o;
}
function addDaysISO(base,days){const d=new Date(base||Date.now());d.setDate(d.getDate()+days);return d.toISOString()}
function fmtDate(v){try{return new Intl.DateTimeFormat('en-IN',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(v))}catch{return '—'}}
function fmtDay(v){try{return new Intl.DateTimeFormat('en-IN',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(v))}catch{return '—'}}
function statusClass(s){return String(s||'Placed').toLowerCase().replace(/\s+/g,'-')}
function activeOffer(){
  const o=state.settings.offer||{};if(!o.enabled)return false;
  const now=Date.now(),start=o.startAt?new Date(o.startAt).getTime():0,end=o.endAt?new Date(o.endAt).getTime():Infinity;
  return now>=start&&now<end;
}
function offerRemaining(){const end=state.settings.offer?.endAt?new Date(state.settings.offer.endAt).getTime():0;return Math.max(0,end-Date.now())}
function fmtTimer(ms){const total=Math.max(0,Math.floor(ms/1000)),d=Math.floor(total/86400),h=Math.floor((total%86400)/3600),m=Math.floor((total%3600)/60),s=total%60;return `${d?d+'d ':''}${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}

function supabaseHeaders(extra={}){return Object.assign({'apikey':SUPABASE_PUBLISHABLE_KEY,'Authorization':`Bearer ${SUPABASE_PUBLISHABLE_KEY}`,'Content-Type':'application/json'},extra)}
async function supabaseRequest(url=SUPABASE_REST,options={}){const res=await fetch(url,{...options,headers:supabaseHeaders(options.headers||{})});const text=await res.text();let data=null;try{data=text?JSON.parse(text):null}catch{}if(!res.ok)throw new Error(data?.message||data?.error_description||text||`HTTP ${res.status}`);return data}

async function saveOrderToSupabase(order){
  try{
    const dbId=Number(`${Date.now()}${String(Math.floor(Math.random()*1000)).padStart(3,'0')}`);
    order.cloudRowId=order.cloudRowId||dbId;
    const row={id:Number(order.cloudRowId),'Customer name':order.customer?.name||'','Customer address':`${order.customer?.address||''}, ${order.customer?.city||''}, ${order.customer?.state||''}, ${order.customer?.pincode||''}`,'Product name':JSON.stringify(order),'Customer number':order.customer?.phone||'','Product price':String(order.total??0),'Product size':(order.items||[]).map(x=>`${x.name||x.id||product(x.id)?.name||''} x${x.qty||1} ${x.size||''} ${x.color||''}`).join(' | ')};
    await supabaseRequest(order.cloudRowId===dbId?SUPABASE_REST:`${SUPABASE_REST}?id=eq.${encodeURIComponent(order.cloudRowId)}`,{method:order.cloudRowId===dbId?'POST':'PATCH',headers:{'Prefer':'return=minimal'},body:JSON.stringify(row)});return true;
  }catch(e){console.error(e);toast(`Cloud order save failed: ${e.message||'Supabase error'}`);return false}
}
async function loadCloudOrderById(id){try{const data=await supabaseRequest(`${SUPABASE_REST}?select=*&order=id.desc`);for(const row of (data||[])){let o=null;try{o=JSON.parse(row['Product name'])}catch{}if(o?.id===id){o.cloudRowId=row.id;return ensureOrderTracking(o)}}}catch{}return null}

function applyLocalOrder(order){state.orders.unshift(ensureOrderTracking(order));state.profile=mergeDeep(state.profile,order.customer||{});state.cart=[];save()}
async function finalizeOrder(order,{localOnly=false}={}){const cloudSaved=localOnly?true:await saveOrderToSupabase(order);if(!cloudSaved)return false;applyLocalOrder(order);render();showSuccess(order);return true}
function showSuccess(order){closeModal();const box=document.createElement('div');box.className='success-toast';box.innerHTML=`<div class="success-icon">✓</div><div><strong>Order ${esc(order.id)} received</strong><span>${order.payment==='cod'?`20% advance pending verification · 80% on delivery`:`Payment status: ${esc(order.paymentStatus||'pending')}`}</span></div>`;document.body.appendChild(box);setTimeout(()=>box.remove(),5200)}

function logo(){return `<a class="logo" href="index.html" aria-label="${esc(state.settings.brand)} home"><span class="logo-frame"><img class="logo-image" src="${LOGO_SRC}" alt="${esc(state.settings.brand)} logo"></span><span class="logo-text">${esc(state.settings.brand)}<small>${esc(state.settings.tagline)}</small></span></a>`}
function offerStrip(){if(!activeOffer())return '';clearInterval(activeOfferTimer);const o=state.settings.offer;const end=o.endAt?new Date(o.endAt).toLocaleString('en-IN',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):'Limited time';const id='offerCount';activeOfferTimer=setInterval(()=>{const el=document.getElementById(id);if(!el){clearInterval(activeOfferTimer);return}el.textContent=fmtTimer(offerRemaining());if(offerRemaining()<=0){clearInterval(activeOfferTimer);render()}},1000);return `<div class="offer-strip"><div class="container offer-inner"><div><b>${esc(o.headline)}</b><span>${esc(o.text)}</span></div><div class="offer-code"><span>CODE: <strong>${esc(o.coupon||'—')}</strong></span><em id="${id}">${fmtTimer(offerRemaining())}</em><small>Ends ${esc(end)}</small></div></div></div>`}
function iconSvg(type){const icons={user:`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 21a8 8 0 0 0-16 0M12 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8Z"/></svg>`,heart:`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.8 8.6c0 5.3-8.8 10.1-8.8 10.1S3.2 13.9 3.2 8.6A4.6 4.6 0 0 1 12 6.1a4.6 4.6 0 0 1 8.8 2.5Z"/></svg>`,bag:`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6.5 8.5h11l1 12h-13l1-12Z"/><path d="M9 9V6a3 3 0 0 1 6 0v3"/></svg>`,menu:`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M4 12h16M4 17h16"/></svg>`};return icons[type]||''}
function header(){return `${offerStrip()}<header class="header"><div class="container nav"><button type="button" class="mobile-menu" aria-label="Open menu" onclick="openMobileMenu()">${iconSvg('menu')}</button>${logo()}<nav id="nav" class="nav-links"><a href="index.html">Home</a><a href="shop.html">Shop</a><a href="categories.html">Categories</a><a href="wishlist.html">Wishlist</a><a href="tracking.html">Track Order</a><a href="help-care.html">Help & Care</a></nav><div class="search-wrap"><input id="topSearch" class="search" placeholder="Search products, category or barcode…" onfocus="renderSearchOverlay('')" oninput="search(this.value)"><span class="search-icon">⌕</span><button type="button" class="scan-btn" title="Scan barcode" aria-label="Scan barcode" onclick="startBarcodeScan()">▥</button></div><div class="nav-actions"><a class="icon-btn profile-action" href="customer-details.html" title="Customer details" aria-label="Customer details">${iconSvg('user')}<span class="action-label">Details</span></a><a class="icon-btn wishlist-action" href="wishlist.html" title="Wishlist" aria-label="Wishlist">${iconSvg('heart')}<span class="badge">${state.wishlist.length||''}</span><span class="action-label">Wishlist</span></a><button type="button" class="icon-btn" title="Shopping bag" aria-label="Shopping bag" onclick="openBag()">${iconSvg('bag')}<span class="badge">${totalItems()||''}</span><span class="action-label">Bag</span></button></div></div></header>`}
function hero(){return `<section class="hero"><div class="hero-media"><img src="${esc(state.settings.heroImage||IMG.hero)}" alt="Kryven Era collection"><div class="hero-fade"></div>${state.settings.heroVideo?`<video autoplay muted loop playsinline src="${esc(state.settings.heroVideo)}"></video>`:''}</div><div class="container hero-grid"><div class="hero-copy"><div class="kicker">KRYVEN ERA · PREMIUM STREETWEAR</div><h1>${esc(state.settings.heroTitle)}</h1><p>${esc(state.settings.heroText)}</p><div class="hero-cta"><a class="btn primary" href="shop.html">Explore Collection →</a><button class="btn ghost" onclick="openCategory('T-Shirts')">Shop the Drop</button></div><div class="hero-highlights"><span>PISTA / SILVER / GOLD</span><span>SIZE-AWARE STOCK</span><span>TRACKED DELIVERY</span></div></div><div class="hero-badge"><span>NEW DROP</span><b>26</b><small>Limited edits</small></div></div></section>`}
function categories(){const cats=['T-Shirts','Hoodies','Pants','Jackets','Accessories'];return `<section class="section"><div class="container"><div class="section-head"><div><div class="eyebrow">01 / COLLECTIONS</div><h2>The Era, Your Way.</h2></div><p class="muted">Clean silhouettes, metallic details and everyday streetwear.</p></div><div class="categories">${cats.map((c,i)=>{const p=state.products.find(x=>x.category===c)||state.products[i%state.products.length];return `<button class="cat" onclick="openCategory('${esc(c)}')"><img src="${esc(p?.images?.[0]||IMG.hero)}" alt="${esc(c)}"><span class="cat-index">0${i+1}</span><div class="cat-shade"></div><div class="cat-info"><b>${esc(c)}</b><span>${state.products.filter(x=>x.category===c).length} pieces →</span></div></button>`}).join('')}</div></div></section>`}
function colorMeta(c){const o=typeof c==='string'?{name:c,hex:COLOR_LIBRARY[c]||'#9ca3aa',enabled:true}:c;return o}
function colorSwatches(p,small=false){const arr=(p.colors||[]).map(colorMeta).filter(x=>x.enabled!==false);return arr.length?`<div class="swatch-row">${arr.slice(0,5).map(c=>`<span class="swatch ${small?'small':''}" title="${esc(c.name)}" style="--swatch:${esc(c.hex)}"></span>`).join('')}</div>`:''}
function productCard(p){const wished=state.wishlist.includes(p.id);const href=`product.html?id=${encodeURIComponent(p.id)}`;return `<article class="card"><a class="card-link" href="${href}" aria-label="View ${esc(p.name)}"><div class="card-media"><img src="${esc(p.images?.[0]||IMG.hero)}" alt="${esc(p.name)}" loading="lazy"><span class="pill">${esc(p.discount||'LIMITED')}</span><span class="quick-label">VIEW PRODUCT</span></div><div class="card-body"><div class="eyebrow">${esc(p.category)} · ${esc(p.id)}</div><h3>${esc(p.name)}</h3><div class="meta">★ ${p.rating||5} · ${p.reviews||0} reviews</div><div class="price-row"><b class="price">${money(p.price)}</b><span class="mrp">${money(p.mrp)}</span><span class="discount">${esc(p.discount||'')}</span></div><div class="card-foot"><div class="size-row">${Object.entries(p.sizes||{}).map(([s,on])=>`<span class="size ${on?'':'off'}">${s}</span>`).join('')}</div>${colorSwatches(p,true)}</div></div></a><button type="button" class="like ${wished?'active':''}" aria-label="${wished?'Remove from wishlist':'Add to wishlist'}" onclick="event.preventDefault();event.stopPropagation();toggleWishlist('${esc(p.id)}')">${wished?'♥':'♡'}</button></article>`}
function shop(){return `<section class="section section-tight"><div class="container"><div class="drop-head"><div><div class="eyebrow">02 / THE DROP</div><h2>Featured Products.</h2></div><div class="chips"><button class="chip gold" onclick="openCategory('All')">View all</button>${['T-Shirts','Hoodies','Pants','Jackets','Accessories'].map(c=>`<button class="chip" onclick="openCategory('${c}')">${c}</button>`).join('')}</div></div><div class="drop-ribbon"><span>LIMITED EDIT</span><b>${esc(state.settings.deliveryNote)}</b><span>CODE ${esc(state.settings.offer?.coupon||'KRYVEN10')}</span></div><div class="product-grid">${state.products.map(productCard).join('')}</div></div></section>`}
function trust(){return `<section class="section section-tight"><div class="container trust-grid"><div class="trust-card"><b>Premium Fabric</b><span>Heavyweight, soft and made for daily wear.</span></div><div class="trust-card"><b>Flexible Payment</b><span>COD with 20% now + 80% after delivery, UPI and cards.</span></div><div class="trust-card"><b>Size Controls</b><span>Admin can enable or disable each size and colour.</span></div><div class="trust-card"><b>Tracked Delivery</b><span>Live order status, ETA, courier and tracking number.</span></div></div></section>`}
function footer(){return `<footer class="footer"><div class="container footer-grid"><div><div>${logo()}</div><p class="muted">A refined storefront system with an owner-controlled catalogue, offers, stock, sizes, colours and payment settings.</p></div><div><b>SHOP</b><a href="shop.html">All products</a><a href="categories.html">Categories</a><a href="wishlist.html">Wishlist</a></div><div><b>ORDER</b><a href="checkout.html">Checkout</a><a href="tracking.html">Track order</a><a href="customer-details.html">Customer details</a></div><div><b>SUPPORT</b><a href="help-care.html">Help & Care</a><a href="reviews.html">Reviews</a><a href="admin.html">Admin Panel</a><a target="_blank" href="https://wa.me/${esc(state.settings.whatsapp)}">WhatsApp</a></div></div><div class="container footer-note">© 2026 ${esc(state.settings.brand)} · White Pista / Silver / Gold Edition</div></footer>`}
function pageShell(title,content){return `${header()}<main class="page-main container"><div class="page-title"><div class="eyebrow">KRYVEN ERA</div><h1>${esc(title)}</h1></div>${content}</main>${footer()}${drawDrawer()}${drawModal()}`}
function drawDrawer(){return `<div id="drawer" class="drawer" aria-hidden="true"><div class="drawer-panel" id="drawerPanel"></div></div>`}
function drawModal(){return `<div id="modal" class="modal" aria-hidden="true"><div class="modal-card" id="modalCard"></div></div>`}
function lockOverlayScroll(){document.documentElement.classList.add('overlay-open');document.body.classList.add('overlay-open')}
function unlockOverlayScroll(){document.documentElement.classList.remove('overlay-open');document.body.classList.remove('overlay-open')}
function openDrawer(content){const d=document.getElementById('drawer');if(!d)return;const panel=document.getElementById('drawerPanel');panel.innerHTML=content;d.classList.add('show');d.setAttribute('aria-hidden','false');lockOverlayScroll();d.onclick=e=>{if(e.target===d)closeDrawer()};panel.onclick=e=>e.stopPropagation()}
function closeDrawer(){const d=document.getElementById('drawer');if(!d)return;d.classList.remove('show');d.setAttribute('aria-hidden','true');unlockOverlayScroll()}
function openModal(content){const m=document.getElementById('modal');if(!m)return;const card=document.getElementById('modalCard');card.innerHTML=content;m.classList.add('show');m.setAttribute('aria-hidden','false');lockOverlayScroll();m.onclick=e=>{if(e.target===m)closeModal()};card.onclick=e=>e.stopPropagation()}
function closeModal(){const m=document.getElementById('modal');if(!m)return;m.classList.remove('show');m.setAttribute('aria-hidden','true');unlockOverlayScroll()}

function openCategory(cat){const items=cat==='All'?state.products:state.products.filter(p=>p.category===cat);openModal(`<div class="modal-top"><div><div class="eyebrow">COLLECTION</div><h3>${esc(cat)}</h3></div><button type="button" class="drawer-close" onclick="closeModal()">×</button></div><div class="modal-pad"><div class="product-grid">${items.map(productCard).join('')}</div></div>`)}
function openProduct(id){const p=product(id);if(!p)return;const sizes=Object.entries(p.sizes||{}),activeSize=sizes.find(([s,on])=>on)?.[0]||'';const colors=(p.colors||[]).map(colorMeta).filter(x=>x.enabled!==false);const activeColor=colors[0]?.name||'';window.__selected={id,size:activeSize,color:activeColor};openModal(`<div class="modal-top"><div><div class="eyebrow">${esc(p.category)} · ${esc(p.id)}</div><h3>${esc(p.name)}</h3></div><button type="button" class="drawer-close" onclick="closeModal()">×</button></div><div class="product-modal"><div class="modal-gallery"><div class="thumbs">${p.images.map((im,i)=>`<button class="thumb ${i===0?'active':''}" onclick="setMainImage(${i},'${esc(p.id)}')"><img src="${esc(im)}" alt=""></button>`).join('')}</div><div class="main-shot"><img id="mainProductImage" src="${esc(p.images[0])}" alt="${esc(p.name)}"></div></div><div class="product-info"><div class="eyebrow">${esc(p.category)}</div><h1>${esc(p.name)}</h1><div class="price-row"><b class="price">${money(p.price)}</b><span class="mrp">${money(p.mrp)}</span><span class="discount">${esc(p.discount)}</span></div><p class="desc">${esc(p.description)}</p><div class="detail-label">COLOUR</div><div class="color-choice" id="colorOptions">${colors.map((c,i)=>`<button class="color-option ${i===0?'selected':''}" onclick="selectProductColor('${esc(c.name)}')"><span class="swatch" style="--swatch:${esc(c.hex)}"></span><span>${esc(c.name)}</span></button>`).join('')}</div><div class="detail-label">SIZE / AVAILABILITY</div><div class="opt-row" id="sizeOptions">${sizes.map(([s,on])=>`<button class="opt ${on?'':'disabled'} ${s===activeSize?'selected':''}" ${on?`onclick="selectProductSize('${s}')"`:''}>${s}${on?'':' · OUT'}</button>`).join('')}</div>${colorSwatches(p)?`<div class="muted tiny">Tap a colour to see its name and swatch.</div>`:''}<div class="product-actions"><button class="btn primary" onclick="confirmAdd('${esc(p.id)}')">Add to Bag →</button><button class="btn ghost" onclick="buyNow('${esc(p.id)}')">Buy Now</button></div><div class="mini-trust"><span>✓ secure checkout</span><span>✓ tracked delivery</span><span>✓ 20/80 COD</span></div></div></div><div class="product-lower"><div><div class="eyebrow">PRODUCT DETAILS</div><h4>Made for the era.</h4>${(p.features||[]).map(f=>`<div class="feature">✓ ${esc(f)}</div>`).join('')}</div><div class="rating-box"><div class="stars">★★★★★</div><b>${p.rating||5}</b><span>${p.reviews||0} reviews</span></div></div></div>`)}
function setMainImage(i,id){const p=product(id);const img=document.getElementById('mainProductImage');if(!p||!img)return;img.src=p.images[i];document.querySelectorAll('.thumb').forEach((x,n)=>x.classList.toggle('active',n===i))}
function selectProductSize(size){if(!window.__selected)return;window.__selected.size=size;document.querySelectorAll('#sizeOptions .opt').forEach(b=>b.classList.toggle('selected',b.textContent.trim().startsWith(size)))}
function selectProductColor(name){if(!window.__selected)return;window.__selected.color=name;document.querySelectorAll('#colorOptions .color-option').forEach(b=>b.classList.toggle('selected',b.textContent.trim()===name));toast(`${name} selected`)}
function addToBag(id,size,color='Black'){const p=product(id);if(!p)return;if(!size||!p.sizes[size]){toast('Please choose an available size');return}const c=colorMeta((p.colors||[]).find(x=>colorMeta(x).name===color));if(c.enabled===false){toast('That colour is disabled');return}const line=state.cart.find(x=>x.id===id&&x.size===size&&x.color===color);if(line)line.qty++;else state.cart.push({id,size,color,qty:1,name:p.name,image:p.images?.[0]||''});save();toast('✓ Added to bag');render()}
function toggleWishlist(id){state.wishlist=state.wishlist.includes(id)?state.wishlist.filter(x=>x!==id):[...state.wishlist,id];save();toast(state.wishlist.includes(id)?'Added to wishlist':'Removed from wishlist');render()}
function changeQty(i,d){const row=state.cart[i];if(!row)return;row.qty=Math.max(0,row.qty+d);if(row.qty===0)state.cart.splice(i,1);save();render()}
function openBag(){if(!state.cart.length){openDrawer(`<div class="drawer-head"><h3>Your Bag</h3><button type="button" class="drawer-close" onclick="closeDrawer()">×</button></div><div class="empty-state">Your bag is empty.<a class="btn primary" href="shop.html" onclick="closeDrawer()">Explore collection →</a></div>`);return}const sub=cartSubtotal();openDrawer(`<div class="drawer-head"><h3>Your Bag · ${totalItems()}</h3><button type="button" class="drawer-close" onclick="closeDrawer()">×</button></div><div class="drawer-items">${state.cart.map((x,i)=>{const p=product(x.id);return `<div class="bag-item"><img src="${esc(x.image||p?.images?.[0]||IMG.hero)}" alt=""><div><b>${esc(p?.name||x.name||x.id)}</b><span>${esc(x.color)} · ${esc(x.size)}</span><div class="qty"><button onclick="changeQty(${i},-1)">−</button><b>${x.qty}</b><button onclick="changeQty(${i},1)">+</button></div></div><strong>${money((p?.price||0)*x.qty)}</strong></div>`}).join('')}</div><div class="drawer-foot"><div class="totals"><div><span>Subtotal</span><b>${money(sub)}</b></div><div><span>Shipping</span><b>${money(shipping())}</b></div><div class="total"><span>Total</span><b>${money(sub+shipping())}</b></div></div><button class="btn primary full" onclick="closeDrawer();openCheckout()">Proceed to Checkout →</button></div>`)}
function openProfile(){const p=state.profile;openDrawer(`<div class="drawer-head"><h3>Customer Details</h3><button type="button" class="drawer-close" onclick="closeDrawer()">×</button></div><div class="profile-tip">Your name, phone and email can be saved once and will auto-fill future orders.</div><div class="form-section compact-form"><div class="form-grid"><div class="field"><label>NAME</label><input id="pfName" value="${esc(p.name)}"></div><div class="field"><label>PHONE</label><input id="pfPhone" value="${esc(p.phone)}" inputmode="tel"></div><div class="field"><label>EMAIL <span>(optional)</span></label><input id="pfEmail" value="${esc(p.email)}" type="email"></div><div class="field"><label>CITY</label><input id="pfCity" value="${esc(p.city)}"></div><div class="field"><label>STATE</label><input id="pfState" value="${esc(p.state)}"></div><div class="field"><label>PINCODE</label><input id="pfPin" value="${esc(p.pincode)}" inputmode="numeric"></div><div class="field full-span"><label>ADDRESS</label><textarea id="pfAddress">${esc(p.address)}</textarea></div><div class="field full-span"><label>LANDMARK <span>(optional)</span></label><input id="pfLandmark" value="${esc(p.landmark||'')}"></div></div><button class="btn primary full" onclick="saveProfile()">Save Details</button></div>`)}
function collectProfileFrom(prefix='pf'){const p={name:document.getElementById(`${prefix}Name`).value.trim(),phone:document.getElementById(`${prefix}Phone`).value.trim(),email:document.getElementById(`${prefix}Email`).value.trim(),city:document.getElementById(`${prefix}City`).value.trim(),state:document.getElementById(`${prefix}State`).value.trim(),pincode:document.getElementById(`${prefix}Pin`).value.trim(),address:document.getElementById(`${prefix}Address`).value.trim(),landmark:document.getElementById(`${prefix}Landmark`)?.value.trim()||''};return p}
function saveProfile(){state.profile=collectProfileFrom();save();localStorage.setItem(PROFILE_SEEN_KEY,'1');toast('Customer details saved');closeDrawer();render()}
function search(q){q=q.trim().toLowerCase();if(!q){renderSearchOverlay('');return}state.searches[q]=(state.searches[q]||0)+1;save();const matches=state.products.filter(p=>(p.name+' '+p.category+' '+p.barcode+' '+p.id).toLowerCase().includes(q));renderSearchOverlay(q,matches)}
function renderSearchOverlay(q,matches=[]){let ov=document.getElementById('searchOverlay');if(!ov){ov=document.createElement('div');ov.id='searchOverlay';ov.className='search-overlay';document.body.appendChild(ov)}const trending=Object.entries(state.searches).sort((a,b)=>b[1]-a[1]).slice(0,5);ov.innerHTML=`<div class="search-panel"><div class="search-panel-head"><b>Search the Era</b><button type="button" onclick="document.getElementById('searchOverlay').remove()">×</button></div><div class="chips">${trending.map(([t])=>`<button class="chip gold" onclick="document.getElementById('topSearch').value='${esc(t)}';search('${esc(t)}')">${esc(t)}</button>`).join('')}</div><div class="search-results">${q?(matches.length?matches.map(p=>`<a class="search-result" href="product.html?id=${encodeURIComponent(p.id)}"><img src="${esc(p.images?.[0]||IMG.hero)}"><span><b>${esc(p.name)}</b><small>${esc(p.category)} · ${money(p.price)}</small></span></a>`).join(''):'<div class="empty-state small">No products found.</div>'):'<div class="muted">Type a product, category or barcode.</div>'}</div></div>`}
function openMobileMenu(){openDrawer(`<div class="drawer-head"><div><div class="eyebrow">KRYVEN ERA</div><h3>Explore the store</h3></div><button type="button" class="drawer-close" onclick="closeDrawer()">×</button></div><nav class="mobile-nav-drawer" aria-label="Mobile navigation"><a href="index.html">Home <span>→</span></a><a href="shop.html">Shop <span>→</span></a><a href="categories.html">Categories <span>→</span></a><a href="wishlist.html">Wishlist <span>♡ ${state.wishlist.length||''}</span></a><a href="tracking.html">Track Order <span>→</span></a><a href="customer-details.html">Customer Details <span>→</span></a><a href="help-care.html">Help & Care <span>→</span></a></nav><div class="mobile-menu-note">Your saved details automatically appear at checkout.</div>`)}
function openWishlist(){const items=state.products.filter(p=>state.wishlist.includes(p.id));openDrawer(`<div class="drawer-head"><h3>Wishlist</h3><button type="button" class="drawer-close" onclick="closeDrawer()">×</button></div>${items.length?`<div class="product-grid drawer-grid">${items.map(productCard).join('')}</div>`:'<div class="empty-state">Your wishlist is empty.</div>'}`)}
function openSupport(){openDrawer(`<div class="drawer-head"><h3>Help & Care</h3><button type="button" class="drawer-close" onclick="closeDrawer()">×</button></div><div class="support-mini"><div class="eyebrow">SUPPORT HOURS</div><h4>${esc(state.settings.supportText)}</h4><p>Questions about sizing, orders, delivery or payments?</p><a class="btn primary full" href="https://wa.me/${esc(state.settings.whatsapp)}?text=${encodeURIComponent('Hello Kryven Era, I need help with my order.')}" target="_blank">Chat on WhatsApp</a><a class="text-link" href="help-care.html" onclick="closeDrawer()">Open Help & Care →</a></div>`)}
function openTracking(){openDrawer(`<div class="drawer-head"><h3>Track Order</h3><button type="button" class="drawer-close" onclick="closeDrawer()">×</button></div><div class="form-section compact-form"><div class="field"><label>ORDER ID</label><input id="trackId" placeholder="KE-2026-XXXX"></div><div class="field"><label>PHONE</label><input id="trackPhone" inputmode="tel" placeholder="Optional"></div><button class="btn primary full" onclick="trackOrder()">Track Order →</button><div id="trackResult"></div></div>`)}
async function trackOrder(){const id=document.getElementById('trackId')?.value.trim(),phone=document.getElementById('trackPhone')?.value.trim()||'';if(!id)return toast('Enter your order ID');let o=state.orders.find(x=>x.id===id)||await loadCloudOrderById(id);if(o&&phone&&o.customer?.phone!==phone)o=null;document.getElementById('trackResult').innerHTML=o?trackingCard(o):'<div class="empty-state small">Order not found.</div>'}
function trackingCard(o){ensureOrderTracking(o);return `<div class="tracking-card"><div class="summary-row"><span>${esc(o.id)}</span><span class="status ${statusClass(o.status)}">${esc(o.status)}</span></div><p class="muted">${esc(o.customer?.name||'Customer')} · ${fmtDate(o.createdAt)}</p><div class="eta-box"><span>EXPECTED DELIVERY</span><b>${fmtDay(o.expectedDeliveryDate)}</b><small>${esc(o.deliveryWindow)}</small></div><div class="timeline">${STATUS_FLOW.map((s,i)=>{const e=o.timeline.find(x=>x.status===s);return `<div class="timeline-item ${e?'done':''} ${o.status===s?'current':''}"><span>${e?'✓':String(i+1).padStart(2,'0')}</span><div><b>${s}</b><small>${e?fmtDate(e.at):'Pending'}</small><em>${e?esc(e.note||STATUS_COPY[s]||s):'Not reached yet'}</em></div></div>`}).join('')}</div></div>`}

function openCheckout(){if(!state.cart.length){toast('Add at least one product before checkout');return}if(location.pathname.endsWith('checkout.html')){render();return}location.href='checkout.html'}
function discountAmount(sub,code){const o=state.settings.offer;if(code&&activeOffer()&&code.toUpperCase()===(o.coupon||'').toUpperCase())return Math.round(sub*.10);return code==='KRYVEN10'?Math.round(sub*.10):0}
function checkoutMarkup(){if(!state.cart.length)return '<div class="empty-state"><h2>Your bag is empty.</h2><a class="btn primary" href="shop.html">Explore Collection →</a></div>';const sub=cartSubtotal();const paymentEnabled=state.settings.payments;return `<div class="checkout-grid"><div><div class="checkout-card"><div class="panel-title"><div><div class="eyebrow">01 / DELIVERY</div><h3>Shipping details</h3></div><span class="chip gold">Profile auto-filled</span></div><div class="form-grid"><div class="field"><label>NAME *</label><input id="coName" value="${esc(state.profile.name)}"></div><div class="field"><label>PHONE *</label><input id="coPhone" value="${esc(state.profile.phone)}" inputmode="tel"></div><div class="field"><label>EMAIL <span>(optional)</span></label><input id="coEmail" value="${esc(state.profile.email)}" type="email"></div><div class="field"><label>CITY *</label><input id="coCity" value="${esc(state.profile.city)}"></div><div class="field"><label>STATE *</label><input id="coState" value="${esc(state.profile.state)}"></div><div class="field"><label>PINCODE *</label><input id="coPin" value="${esc(state.profile.pincode)}" inputmode="numeric"></div><div class="field full-span"><label>FULL ADDRESS *</label><textarea id="coAddress">${esc(state.profile.address)}</textarea></div><div class="field full-span"><label>LANDMARK <span>(optional)</span></label><input id="coLandmark" value="${esc(state.profile.landmark||'')}"></div></div></div><div class="checkout-card"><div class="panel-title"><div><div class="eyebrow">02 / OFFER</div><h3>Apply a discount</h3></div></div><div class="coupon-row"><input id="coupon" placeholder="Enter coupon" value=""><button class="btn" onclick="applyCheckoutCoupon()">Apply</button></div><div id="couponMsg" class="muted"></div></div><div class="checkout-card"><div class="panel-title"><div><div class="eyebrow">03 / PAYMENT</div><h3>Choose payment</h3></div></div><div class="payment-choice-list">${paymentEnabled.cod?`<label class="payment-choice"><input name="pay" type="radio" value="cod" checked><span><b>Cash on Delivery</b><small>20% now · 80% after delivery</small></span><strong>20% + 80%</strong></label>`:''}${paymentEnabled.upi?`<label class="payment-choice"><input name="pay" type="radio" value="upi"><span><b>UPI Payment</b><small>Scan QR or open your UPI app</small></span><strong>UPI</strong></label>`:''}${paymentEnabled.card?`<label class="payment-choice"><input name="pay" type="radio" value="card"><span><b>Credit / Debit Card</b><small>${state.settings.cashfree.enabled?'Cashfree checkout':'Cashfree connection required'}</small></span><strong>CARD</strong></label>`:''}</div><div class="payment-note">${state.settings.cashfree.enabled?'Cashfree is ready for the configured backend endpoint.':'Admin can enable Cashfree from Payments and point it to a secure backend create-order endpoint.'}</div></div></div><aside class="summary-card checkout-summary"><div class="eyebrow">04 / ORDER SUMMARY</div><h3>Ready to place.</h3><div class="summary-row"><span>Subtotal</span><b>${money(sub)}</b></div><div class="summary-row"><span>Shipping</span><b>${money(shipping())}</b></div><div class="summary-row"><span>Discount</span><b id="discountLine">—</b></div><div class="summary-row total"><span>Total</span><b id="sumTotal">${money(sub+shipping())}</b></div><div class="offer-note">${activeOffer()?`Offer live · use <strong>${esc(state.settings.offer.coupon||'KRYVEN10')}</strong>`:'Offer currently inactive'}</div><button class="btn primary full" onclick="placeOrder()">Place Order Securely →</button><p class="tiny muted">You cannot place an order without a product in your bag. Required shipping details are marked *.</p></aside></div>`}
function saveCheckoutProfile(){state.profile={name:document.getElementById('coName').value.trim(),phone:document.getElementById('coPhone').value.trim(),email:document.getElementById('coEmail').value.trim(),city:document.getElementById('coCity').value.trim(),state:document.getElementById('coState').value.trim(),pincode:document.getElementById('coPin').value.trim(),address:document.getElementById('coAddress').value.trim(),landmark:document.getElementById('coLandmark')?.value.trim()||''};save()}
function applyCheckoutCoupon(){const code=(document.getElementById('coupon')?.value||'').trim().toUpperCase(),amt=discountAmount(cartSubtotal(),code);document.getElementById('couponMsg').textContent=amt?`Applied ${code} · you save ${money(amt)}`:'Coupon not valid or offer expired';const el=document.getElementById('discountLine');const total=document.getElementById('sumTotal');if(el)el.textContent=amt?`−${money(amt)}`:'—';if(total)total.textContent=money(cartTotal(amt));window.__checkoutDiscount=amt;window.__checkoutCoupon=code}
function buildOrder(payment,discount=0){const createdAt=new Date().toISOString(),total=cartTotal(discount);const id=`KE-${new Date().getFullYear()}-${String(Date.now()).slice(-6)}`;return ensureOrderTracking({id,createdAt,status:'Placed',customer:structuredClone(state.profile),items:state.cart.map(x=>{const p=product(x.id);return {id:x.id,name:p.name,size:x.size,color:x.color,qty:x.qty,image:p.images?.[0]||''}}),subtotal:cartSubtotal(),discount,total,payment,advancePaid:payment==='cod'?0:0,remainingDue:total,paymentStatus:payment==='cod'?'advance_pending':'pending',referralSource:localStorage.getItem('kryven-era-referral-source')||'',offerCode:window.__checkoutCoupon||''})}
function validateCheckout(){if(!state.cart.length){toast('Add a product first');return false}saveCheckoutProfile();const p=state.profile;if(!p.name||!p.phone||!p.address||!p.city||!p.state||!/^[0-9]{6}$/.test(p.pincode)){toast('Complete name, phone, address, city, state and 6-digit pincode');return false}if(p.phone.replace(/\D/g,'').length<10){toast('Enter a valid phone number');return false}if(p.email&&!/^\S+@\S+\.\S+$/.test(p.email)){toast('Check the email address');return false}return true}
async function placeOrder(){if(!validateCheckout())return;const payment=document.querySelector('input[name="pay"]:checked')?.value;if(!payment){toast('Select a payment method');return}const order=buildOrder(payment,window.__checkoutDiscount||0);if(payment==='cod'){await handleCodOrder(order);return}if(payment==='card'&&!state.settings.cashfree.enabled){toast('Credit/debit card needs Cashfree to be connected in Admin → Payments');return}if(state.settings.cashfree.enabled){await startCashfree(order);return}if(payment==='upi'){await startUPI(order);return}}
async function handleCodOrder(order){order.advanceRequired=Math.round(order.total*(Number(state.settings.codAdvancePercent||20)/100));order.remainingDue=Math.max(0,order.total-order.advanceRequired);if(state.settings.cashfree.enabled){await startCashfree(order);return}await saveAndShowPending(order,`COD selected · ${state.settings.codAdvancePercent||20}% advance is required now.`);}
async function saveAndShowPending(order,message){const ok=await saveOrderToSupabase(order);if(!ok)return;state.orders.unshift(order);state.profile=mergeDeep(state.profile,order.customer);state.cart=[];save();openModal(`<div class="payment-modal"><div class="modal-top"><div><div class="eyebrow">ORDER RECEIVED</div><h2>${esc(order.id)}</h2></div><button type="button" class="drawer-close" onclick="closeModal()">×</button></div><div class="payment-state"><div class="payment-amount">${money(order.advanceRequired||order.total)}</div><p>${esc(message)}</p>${order.payment==='cod'?`<p><strong>COD split:</strong> ${money(order.advanceRequired)} now · ${money(order.remainingDue)} after delivery.</p>`:''}<div class="qr-fallback"><div class="qr-title">Pay the advance with UPI</div><div id="pendingQr"></div><a class="btn primary full" href="${esc(makeUpiLink(order,order.advanceRequired||order.total))}">Open UPI App →</a><button class="btn ghost full" onclick="markPaymentVerificationPending('${esc(order.id)}')">I have paid — verify payment</button></div><p class="tiny muted">For automatic confirmation, connect Cashfree or your UPI verification backend in the Admin panel.</p></div></div>`);renderUPIQR(makeUpiLink(order,order.advanceRequired||order.total),'pendingQr')}
function makeUpiLink(order,amount){const upi=encodeURIComponent(state.settings.upi||'kryvenera@upi'),name=encodeURIComponent(state.settings.brand||'Kryven Era');return `upi://pay?pa=${upi}&pn=${name}&am=${Number(amount||0).toFixed(2)}&cu=INR&tn=${encodeURIComponent('Kryven Era '+order.id)}`}
async function markPaymentVerificationPending(id){const o=state.orders.find(x=>x.id===id);if(!o)return;o.paymentStatus='verification_pending';save();await saveOrderToSupabase(o);toast('Payment marked for verification');closeModal();render()}
async function startUPI(order){await saveAndShowPending(order,'UPI order created. Complete payment to finish checkout.');}
async function loadCashfreeScript(){if(window.Cashfree)return window.Cashfree;await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://sdk.cashfree.com/js/v3/cashfree.js';s.onload=resolve;s.onerror=reject;document.head.appendChild(s)});return window.Cashfree}
async function startCashfree(order){const cf=state.settings.cashfree||{};if(!cf.checkoutEndpoint){toast('Cashfree backend endpoint is not configured');return}const saved=await saveOrderToSupabase(order);if(!saved)return;order.paymentStatus='gateway_pending';state.orders.unshift(order);state.cart=[];save();try{const res=await fetch(cf.checkoutEndpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({orderId:order.id,amount:paymentAmount(order),customer:order.customer,items:order.items,returnUrl:location.origin+location.pathname+'?payment_return=1'})});if(!res.ok)throw new Error(await res.text());const data=await res.json();if(!data.paymentSessionId)throw new Error('No paymentSessionId returned by backend');const Cashfree=await loadCashfreeScript();const cashfree=Cashfree({mode:cf.mode==='production'?'production':'sandbox'});closeModal();await cashfree.checkout({paymentSessionId:data.paymentSessionId});toast('Cashfree checkout opened.');}catch(e){toast(`Cashfree checkout failed: ${e.message||'error'}`)}}
function paymentAmount(order){return order.payment==='cod'?Number(order.advanceRequired||Math.round(order.total*(Number(state.settings.codAdvancePercent||20)/100))):Number(order.total)}
async function verifyCashfreeReturn(){if(!new URLSearchParams(location.search).has('payment_return'))return;const id=new URLSearchParams(location.search).get('order_id')||new URLSearchParams(location.search).get('orderId');if(!id)return;const o=state.orders.find(x=>x.id===id)||await loadCloudOrderById(id);if(!o)return;const endpoint=state.settings.cashfree.verifyEndpoint;if(!endpoint){toast('Payment submitted. Admin verification is pending.');return}try{const res=await fetch(`${endpoint}?order_id=${encodeURIComponent(id)}`,{cache:'no-store'});if(!res.ok)throw new Error('verification failed');const data=await res.json();if(data?.paid){const amount=paymentAmount(o);o.paymentStatus='paid';o.advancePaid=o.payment==='cod'?amount:o.total;o.remainingDue=Math.max(0,o.total-o.advancePaid);await saveOrderToSupabase(o);state.orders=state.orders.filter(x=>x.id!==o.id).concat([o]);save();toast('Payment verified successfully')}else toast('Payment is not yet confirmed.');}catch{toast('Payment verification is pending.')}history.replaceState({},'',location.pathname)}
async function renderUPIQR(text,targetId='upiQr'){const el=document.getElementById(targetId);if(!el)return;try{if(!window.QRCode){await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/qrcode@1.5.3/build/qrcode.min.js';s.onload=resolve;s.onerror=reject;document.head.appendChild(s)})}const canvas=document.createElement('canvas');await QRCode.toCanvas(canvas,text,{width:200,margin:1});el.innerHTML='';el.appendChild(canvas)}catch{el.innerHTML='<div class="qr-error">QR unavailable — use the UPI button.</div>'}}

function profileGate(){if(!state.settings.profileGateEnabled||localStorage.getItem(PROFILE_SEEN_KEY)==='1')return;openModal(`<div class="welcome-gate"><div class="eyebrow">WELCOME TO KRYVEN ERA</div><h2>Let’s save your details once.</h2><p class="muted">Name and phone are optional here. Anything you enter will be auto-filled when you order. Address and pincode can be added later at checkout.</p><div class="gate-grid"><div class="field"><label>NAME (OPTIONAL)</label><input id="gateName"></div><div class="field"><label>PHONE (OPTIONAL)</label><input id="gatePhone" inputmode="tel"></div><div class="field full-span"><label>EMAIL (OPTIONAL)</label><input id="gateEmail" type="email"></div></div><div class="gate-actions"><button class="btn ghost" onclick="skipProfileGate()">Continue without details</button><button class="btn primary" onclick="finishProfileGate()">Continue →</button></div></div>`)}
function finishProfileGate(){state.profile.name=document.getElementById('gateName').value.trim();state.profile.phone=document.getElementById('gatePhone').value.trim();state.profile.email=document.getElementById('gateEmail').value.trim();save();localStorage.setItem(PROFILE_SEEN_KEY,'1');closeModal();toast('Saved — details will auto-fill at checkout')}
function skipProfileGate(){localStorage.setItem(PROFILE_SEEN_KEY,'1');closeModal()}
function applyTheme(){const t=state.settings.theme||DEFAULT_SETTINGS.theme;document.documentElement.style.setProperty('--pista',t.primary);document.documentElement.style.setProperty('--gold',t.accent);document.documentElement.style.setProperty('--silver',t.silver);document.documentElement.style.setProperty('--ink',t.ink)}
function siteBackground(){const s=state.settings;if(!s.backgroundVideoEnabled||!s.backgroundVideo)return '';return `<div class="site-bg-video"><video autoplay muted loop playsinline src="${esc(s.backgroundVideo)}"></video><div></div></div>`}
function pageContent(){const page=document.body.dataset.page||'home';if(page==='home')return `${hero()}${categories()}${shop()}${trust()}`;if(page==='shop')return shop();if(page==='categories')return categories();if(page==='wishlist'){const items=state.products.filter(p=>state.wishlist.includes(p.id));return `<section class="section"><div class="product-grid">${items.length?items.map(productCard).join(''):'<div class="empty-state">Your wishlist is empty.<a class="btn primary" href="shop.html">Shop Collection →</a></div>'}</div></section>`}if(page==='product'){const p=product(new URLSearchParams(location.search).get('id'));return p?productDetailPage(p):'<div class="empty-state">Product not found.</div>'}if(page==='bag')return bagPage();if(page==='checkout')return checkoutMarkup();if(page==='customer')return customerPage();if(page==='tracking')return `<section class="section"><div class="tracking-layout"><div class="checkout-card"><div class="eyebrow">ORDER LOOKUP</div><h2>Track your delivery.</h2><div class="field"><label>ORDER ID</label><input id="trackId"></div><div class="field"><label>PHONE</label><input id="trackPhone"></div><button class="btn primary full" onclick="trackOrder()">Track Order →</button><div id="trackResult"></div></div><div class="checkout-card"><h3>What you can see</h3><p class="muted">Status, expected arrival, courier, tracking number and delivery timeline.</p></div></div></section>`;if(page==='support')return supportPage();if(page==='reviews')return reviewsPage();if(page==='search')return searchPage();return `${hero()}${categories()}${shop()}${trust()}`}
function productDetailPage(p){const colors=(p.colors||[]).map(colorMeta).filter(x=>x.enabled!==false);return `<section class="section"><div class="product-modal page-product"><div class="modal-gallery"><div class="thumbs">${p.images.map((im,i)=>`<button class="thumb ${i===0?'active':''}" onclick="setMainImage(${i},'${esc(p.id)}')"><img src="${esc(im)}" alt=""></button>`).join('')}</div><div class="main-shot"><img id="mainProductImage" src="${esc(p.images[0])}" alt="${esc(p.name)}"></div></div><div class="product-info"><div class="eyebrow">${esc(p.category)} · ${esc(p.id)}</div><h1>${esc(p.name)}</h1><div class="price-row"><b class="price">${money(p.price)}</b><span class="mrp">${money(p.mrp)}</span><span class="discount">${esc(p.discount)}</span></div><p class="desc">${esc(p.description)}</p><div class="detail-label">COLOUR</div><div class="color-choice">${colors.map(c=>`<div class="color-option static"><span class="swatch" style="--swatch:${esc(c.hex)}"></span><span>${esc(c.name)}</span></div>`).join('')}</div><div class="detail-label">SIZE</div><div class="opt-row">${Object.entries(p.sizes||{}).map(([s,on])=>`<span class="opt ${on?'':'disabled'}">${s}${on?'':' · OUT'}</span>`).join('')}</div><button class="btn primary full" onclick="openProduct('${esc(p.id)}')">Choose size & Add to Bag →</button><div class="mini-trust"><span>✓ 20/80 COD</span><span>✓ UPI</span><span>✓ Card</span></div></div></div><div class="product-lower"><div><div class="eyebrow">DETAILS</div><h2>Built for the era.</h2>${(p.features||[]).map(f=>`<div class="feature">✓ ${esc(f)}</div>`).join('')}</div><div class="rating-box"><div class="stars">★★★★★</div><b>${p.rating||5}</b><span>${p.reviews||0} reviews</span></div></div></section>`}
function bagPage(){if(!state.cart.length)return `<section class="section"><div class="empty-state"><div class="eyebrow">YOUR BAG</div><h2>Nothing here yet.</h2><p>Pick at least one product to continue to checkout.</p><a class="btn primary" href="shop.html">Explore Collection →</a></div></section>`;const sub=cartSubtotal();return `<section class="section"><div class="bag-layout"><div class="bag-list">${state.cart.map((x,i)=>{const p=product(x.id);return `<div class="bag-line"><img src="${esc(x.image||p?.images?.[0]||IMG.hero)}"><div><div class="eyebrow">${esc(p?.category||'')}</div><h3>${esc(p?.name||x.name||x.id)}</h3><p class="muted">${esc(x.color)} · Size ${esc(x.size)}</p><div class="qty"><button onclick="changeQty(${i},-1)">−</button><b>${x.qty}</b><button onclick="changeQty(${i},1)">+</button></div></div><strong>${money((p?.price||0)*x.qty)}</strong></div>`}).join('')}</div><aside class="summary-card"><div class="eyebrow">ORDER SUMMARY</div><h3>Ready when you are.</h3><div class="summary-row"><span>Subtotal</span><b>${money(sub)}</b></div><div class="summary-row"><span>Shipping</span><b>${money(shipping())}</b></div><div class="summary-row total"><span>Total</span><b>${money(sub+shipping())}</b></div><button class="btn primary full" onclick="openCheckout()">Proceed to Checkout →</button></aside></div></section>`}
function customerPage(){const p=state.profile;return `<section class="section"><div class="checkout-card"><div class="eyebrow">PROFILE</div><h2>Customer details.</h2><div class="form-grid"><div class="field"><label>NAME</label><input id="pfName" value="${esc(p.name)}"></div><div class="field"><label>PHONE</label><input id="pfPhone" value="${esc(p.phone)}"></div><div class="field"><label>EMAIL (OPTIONAL)</label><input id="pfEmail" value="${esc(p.email)}"></div><div class="field"><label>CITY</label><input id="pfCity" value="${esc(p.city)}"></div><div class="field"><label>STATE</label><input id="pfState" value="${esc(p.state)}"></div><div class="field"><label>PINCODE</label><input id="pfPin" value="${esc(p.pincode)}"></div><div class="field full-span"><label>ADDRESS</label><textarea id="pfAddress">${esc(p.address)}</textarea></div><div class="field full-span"><label>LANDMARK (OPTIONAL)</label><input id="pfLandmark" value="${esc(p.landmark||'')}"></div></div><button class="btn primary" onclick="saveProfile()">Save Details →</button></div></section>`}
function supportPage(){return `<section class="section"><div class="support-grid"><div class="checkout-card"><div class="eyebrow">HELP & CARE</div><h2>We’re here for your order.</h2><p class="muted">${esc(state.settings.supportText)}</p><a class="btn primary" target="_blank" href="https://wa.me/${esc(state.settings.whatsapp)}?text=${encodeURIComponent('Hello Kryven Era, I need help with my order.')}">Chat on WhatsApp →</a></div><div class="checkout-card"><h3>Payments</h3><p class="muted">COD 20% advance + 80% after delivery, UPI, and card depending on admin settings.</p></div></div></section>`}
function reviewsPage(){return `<section class="section"><div class="review-grid">${state.reviews.length?state.reviews.map(r=>`<article class="review-card"><b>${esc(r.name||'Kryven Customer')}</b><div class="stars">${'★'.repeat(r.rating||5)}${'☆'.repeat(5-(r.rating||5))}</div><p>${esc(r.text||'')}</p></article>`).join(''):'<div class="empty-state">Verified customer reviews appear here after delivery.</div>'}</div></section>`}
function searchPage(){const q=new URLSearchParams(location.search).get('q')||'';const matches=state.products.filter(p=>(p.name+' '+p.category+' '+p.barcode).toLowerCase().includes(q.toLowerCase()));return `<section class="section"><div class="search-page"><div class="search-wrap large"><input class="search" value="${esc(q)}" placeholder="Search" oninput="location.href='search.html?q='+encodeURIComponent(this.value)"></div><div class="product-grid">${matches.map(productCard).join('')||'<div class="empty-state">No matching products found.</div>'}</div></div></section>`}
function render(){applyTheme();const root=document.getElementById('app');if(!root)return;root.innerHTML=siteBackground()+header()+`<main class="${document.body.dataset.page==='home'?'home-main':''}">${document.body.dataset.page==='home'?pageContent():`<div class="container page-shell-title"><div class="page-title"><div class="eyebrow">KRYVEN ERA</div><h1>${esc((document.title||'Kryven Era').replace(/^KRYVEN ERA — /i,'').replace(/^KRYVEN ERA — Wear Your Era$/i,'Store'))}</h1></div>${pageContent()}</div>`}</main>`+footer()+drawDrawer()+drawModal();
  if(document.body.dataset.page==='checkout')setTimeout(()=>{},0);
}
function showReferralOnce(){}
function startBarcodeScan(){
  try{if(!('BarcodeDetector' in window)){toast('Barcode scanning is not supported in this browser.');return}const detector=new BarcodeDetector({formats:['ean_13','ean_8','code_128','code_39','upc_a','upc_e']});navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}}).then(async stream=>{const video=document.createElement('video');video.autoplay=true;video.muted=true;video.playsInline=true;video.className='scanner-video';document.body.appendChild(video);video.srcObject=stream;await video.play();const loop=async()=>{try{const codes=await detector.detect(video);if(codes.length){const value=codes[0].rawValue;stream.getTracks().forEach(t=>t.stop());video.remove();const input=document.getElementById('topSearch');if(input)input.value=value;search(value);return}}catch{}requestAnimationFrame(loop)};loop()}).catch(()=>toast('Camera permission denied. Enter the barcode manually.'))}catch{toast('Barcode scanning unavailable.')}}
window.openModal=openModal;window.closeModal=closeModal;window.closeDrawer=closeDrawer;window.openMobileMenu=openMobileMenu;window.openBag=openBag;window.openCheckout=openCheckout;window.openProduct=openProduct;window.openCategory=openCategory;window.toggleWishlist=toggleWishlist;window.openWishlist=openWishlist;window.openProfile=openProfile;window.openSupport=openSupport;window.openTracking=openTracking;window.trackOrder=trackOrder;window.changeQty=changeQty;window.setMainImage=setMainImage;window.selectProductSize=selectProductSize;window.selectProductColor=selectProductColor;window.confirmAdd=id=>{addToBag(id,window.__selected?.size||'',window.__selected?.color||'');closeModal();openBag()};window.buyNow=id=>{addToBag(id,window.__selected?.size||'',window.__selected?.color||'');closeModal();openCheckout()};window.applyCheckoutCoupon=applyCheckoutCoupon;window.placeOrder=placeOrder;window.saveProfile=saveProfile;window.search=search;window.renderSearchOverlay=renderSearchOverlay;window.startBarcodeScan=startBarcodeScan;window.skipProfileGate=skipProfileGate;window.finishProfileGate=finishProfileGate;window.markPaymentVerificationPending=markPaymentVerificationPending;window.render=render;

(async function boot(){
  // Always start a newly opened page at the top. This prevents Android/Chrome
  // scroll restoration from placing the sticky header over the page title.
  if('scrollRestoration' in history) history.scrollRestoration='manual';
  window.scrollTo(0,0);
  await verifyCashfreeReturn();
  render();
  requestAnimationFrame(()=>window.scrollTo(0,0));
  const noSeen=localStorage.getItem(PROFILE_SEEN_KEY)!=='1';
  if(noSeen&&document.body.dataset.page!=='admin')requestAnimationFrame(profileGate);
})();
